# Crear combinaciones
combinaciones = [
    (item["Idvbox"], item["CC"], item["Ubicación"])
    for item in data
]

# Contar repeticiones
conteo = Counter(combinaciones)

# Construir filas para el DataFrame
filas = []
for (idvbox, cc, ubicacion), cantidad in conteo.items():
    estado = "DIFERENTE" if cantidad == 1 else "IGUALES"
    
    filas.append({
        "idvbox": idvbox,
        "cc": cc,
        "ubicacion": ubicacion,
        "cantidad_repeticion": cantidad,
        "razon": estado
    })

# Crear DataFrame
df = pd.DataFrame(filas)

# Exportar a Excel
df.to_excel("ResultadosAPI.xlsx", index=False)

print("✅ Archivo 'ResultadosAPI.xlsx' generado correctamente")